<script setup lang="ts">
/**
 * The chat composer, where a prompt is written and sent (`design/components/prompt-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/prompt-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import {
  Icon,
  afterRender,
  agentFill,
  agentMember,
  composingKey,
  fitTextarea,
  focusAfterRemoval,
  gateFiles,
  holdFieldEscape,
  promptPick,
  promptToken,
  useListening,
  type FileRejection,
  type IconRole,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/prompt-input.module.css'
import AttachmentChip, { type AttachmentStatus } from './AttachmentChip.vue'
import Button from '../controls/Button.vue'
import Skeleton from '../structure/Skeleton.vue'

export type PromptInputMaxRows = NonNullable<PromptInputProps['maxRows']>

export interface PromptAttachment {
  id: string
  name: string
  size?: number
  status?: AttachmentStatus
  message?: string
}

export interface PromptInputMessages {
  send: string
  stop: string
  attach: string
  remove: (name: string) => string
  uploading: (name: string) => string
  suggestions?: (count: number) => string
  loadingSuggestions?: string
  noSuggestions?: string
}

export interface PromptTriggerOption {
  id: string
  label: string
  description?: string
  icon?: IconRole
  insert?: string
}

export interface PromptTrigger {
  char: string
  label: string
  options: PromptTriggerOption[]
  at?: 'word' | 'start'
  filter?: 'contains' | 'startsWith' | false
  loading?: boolean
  onQueryChange?: (query: string) => void
  onSelect?: (option: PromptTriggerOption) => void
}

export interface PromptInputProps {
  /**
   * The native `accept` syntax (`.pdf`, `image/*`), also applied to drops and pastes.
   */
  accept?: string
  /**
   * The chips in the frame, always controlled by the app.
   */
  attachments?: PromptAttachment[]
  /**
   * Native passthrough, for a screen that has already moved the reader here.
   */
  autoFocus?: boolean
  defaultValue?: string
  disabled?: boolean
  /**
   * One line under the frame with the app's own note about what happens next.
   */
  hint?: string
  id?: string
  /**
   * The field's accessible name, needed because a composer has no visible label.
   */
  label: string
  /**
   * How tall the field may grow before it scrolls, in lines.
   */
  maxRows?: 4 | 6 | 8 | 12
  /**
   * The maximum file size in bytes, above which a file never reaches `onAttach`.
   */
  maxSize?: number
  /**
   * All of the controls' text (generic English defaults), which localized hosts replace.
   */
  messages?: PromptInputMessages
  /**
   * When `false`, only one file is accepted at a time and the rest are rejected as `count`.
   */
  multiple?: boolean
  name?: string
  placeholder?: string
  /**
   * Whether a reply is arriving, which turns send into stop and makes Enter do nothing.
   */
  streaming?: boolean
  /**
   * The characters that open a list of suggestions: `@` for people, `/` for commands.
   */
  triggers?: PromptTrigger[]
  value?: string
}

defineOptions({ name: 'PromptInput', inheritAttrs: false })

const props = withDefaults(defineProps<PromptInputProps>(), {
  attachments: () => [],
  autoFocus: false,
  disabled: false,
  maxRows: 8,
  messages: () => ({
    send: 'Send',
    stop: 'Stop',
    attach: 'Attach',
    remove: (name) => `Remove ${name}`,
    uploading: (name) => `${name}: uploading`,
  }),
  multiple: true,
  streaming: false,
  triggers: () => [],
})
const emit = defineEmits<{
  attach: [files: File[]]
  change: [value: string]
  reject: [rejections: FileRejection[]]
  removeAttachment: [id: string]
  stop: []
  submit: [value: string]
}>()
defineSlots<{
  leading?: (props: Record<string, never>) => unknown
  trailing?: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const listening = useListening()
const uncontrolled = ref(props.defaultValue ?? '')
const dragover = ref(false)
const caret = ref(null as number | null)
const composing = ref(false)
const dismissed = ref(null as number | null)
const highlight = ref({ key: '', index: 0 })
const side = ref('top' as 'top' | 'bottom')
const reported = ref(null as string | null)
const pressed = ref(null as { id: string; at: number } | null)
const chips = useTemplateRef<HTMLElement>('chips')
const end = useTemplateRef<HTMLElement>('end')
const field = useTemplateRef<HTMLElement>('field')
const picker = useTemplateRef<HTMLElement>('picker')
const root = useTemplateRef<HTMLElement>('root')
const toolbar = useTemplateRef<HTMLElement>('toolbar')
const text = computed(() => props.value ?? uncontrolled.value)
const empty = computed(() => text.value.trim() === '' && props.attachments.length === 0)
const attachable = computed(() => listening.attach && !props.disabled)
const setText = computed(
  () => (next: string) => ((uncontrolled.value = next), emit('change', next)),
)
const submit = computed(
  () => () =>
    !props.disabled &&
    !props.streaming &&
    !empty.value &&
    (emit('submit', text.value), props.value === undefined && (uncontrolled.value = '')),
)
const add = computed(
  () => (list: FileList | File[] | null | undefined) =>
    attachable.value &&
    list != null &&
    list.length > 0 &&
    ((gate) => (
      gate.accepted.length > 0 && emit('attach', gate.accepted),
      gate.rejected.length > 0 && emit('reject', gate.rejected)
    ))(
      gateFiles(Array.from(list), {
        accept: props.accept,
        multiple: props.multiple,
        maxSize: props.maxSize,
      }),
    ),
)
const suggesting = computed(() => props.triggers.length > 0)
const token = computed(() =>
  props.disabled ? null : promptToken(text.value, caret.value, props.triggers),
)
const trigger = computed(() =>
  token.value === null ? undefined : props.triggers[token.value.trigger],
)
const open = computed(
  () =>
    token.value !== null && trigger.value !== undefined && token.value.start !== dismissed.value,
)
const query = computed(() => token.value?.query ?? '')
const collator = computed(
  () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
)
const needle = computed(() => query.value.normalize('NFC'))
const matches = computed(
  () => (label: string) =>
    ((candidate: string) =>
      needle.value === '' ||
      (trigger.value?.filter === 'startsWith'
        ? collator.value.compare(candidate.slice(0, needle.value.length), needle.value) === 0
        : Array.from({ length: Math.max(0, candidate.length - needle.value.length + 1) }, (_, at) =>
            candidate.slice(at, at + needle.value.length),
          ).some((part) => collator.value.compare(part, needle.value) === 0)))(
      label.normalize('NFC'),
    ),
)
const shown = computed(() =>
  !open.value || trigger.value === undefined
    ? []
    : trigger.value.filter === false
      ? trigger.value.options
      : trigger.value.options.filter((option) => matches.value(option.label)),
)
const loading = computed(() => open.value && trigger.value?.loading === true)
const listKey = computed(() =>
  open.value && token.value !== null
    ? `${token.value.trigger}:${token.value.start}:${query.value}`
    : '',
)
const sideKey = computed(() =>
  open.value && token.value !== null ? `${token.value.trigger}:${token.value.start}` : null,
)
const active = computed(() =>
  shown.value.length === 0
    ? -1
    : highlight.value.key === listKey.value
      ? Math.min(highlight.value.index, shown.value.length - 1)
      : 0,
)
const listId = computed(() => `${uid}-suggestions`)
const say = computed(() => ({
  suggestions: props.messages.suggestions ?? ((count: number) => `${count} suggestions`),
  loadingSuggestions: props.messages.loadingSuggestions ?? 'Loading suggestions…',
  noSuggestions: props.messages.noSuggestions ?? 'No results',
}))
const announcement = computed(() =>
  !open.value
    ? ''
    : loading.value
      ? say.value.loadingSuggestions
      : shown.value.length === 0
        ? say.value.noSuggestions
        : say.value.suggestions(shown.value.length),
)
const track = computed(() => (element: HTMLTextAreaElement, nextText: string) => {
  if (composing.value || element.value !== nextText) return
  const next =
    element.ownerDocument.activeElement === element &&
    element.selectionStart === element.selectionEnd
      ? element.selectionStart
      : null
  const found = props.disabled ? null : promptToken(nextText, next, props.triggers)
  const closed = found !== null && found.start === dismissed.value ? dismissed.value : null
  caret.value = next
  dismissed.value = closed
  const key =
    found === null || closed !== null ? null : found.trigger + ':' + found.start + ':' + found.query
  if (key === reported.value) return
  reported.value = key
  if (found !== null && key !== null) props.triggers[found.trigger]?.onQueryChange?.(found.query)
})
const pick = computed(() => (index: number) => {
  const option = shown.value[index]
  const at = token.value
  const by = trigger.value
  if (option === undefined || at === null || by === undefined || caret.value === null) return
  const next = promptPick(text.value, at, caret.value, option.insert ?? by.char + option.label)
  setText.value(next.text)
  caret.value = next.caret
  dismissed.value = null
  reported.value = null
  afterRender(() =>
    (field.value as HTMLTextAreaElement | null)?.setSelectionRange(next.caret, next.caret),
  )
  by.onSelect?.(option)
})
const listKeys = computed(() => (event: KeyboardEvent) => {
  const at = token.value
  if (!open.value || at === null) return false
  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
    if (shown.value.length === 0) return false
    event.preventDefault()
    highlight.value = {
      key: listKey.value,
      index:
        event.key === 'ArrowDown'
          ? Math.min(active.value + 1, shown.value.length - 1)
          : Math.max(active.value - 1, 0),
    }
    return true
  }
  if (event.key === 'Enter') {
    if (event.shiftKey || (active.value === -1 && !loading.value)) return false
    event.preventDefault()
    if (active.value !== -1) pick.value(active.value)
    return true
  }
  if (event.key === 'Tab') {
    if (event.shiftKey || active.value === -1) return false
    event.preventDefault()
    pick.value(active.value)
    return true
  }
  if (event.key === 'Escape') {
    // Escape closes the list and keeps the text. A dialog around the composer stays open,
    // because holdEscape has prevented the key's default.
    event.preventDefault()
    event.stopPropagation()
    dismissed.value = at.start
    reported.value = null
    return true
  }
  return false
})
const effect1 = () => {
  field.value && fitTextarea(field.value as HTMLTextAreaElement)
}
onMounted(effect1)
watch(() => text.value, effect1, { flush: 'post' })
const effect2 = () => {
  props.autoFocus &&
    field.value &&
    (field.value.focus(),
    (field.value as HTMLTextAreaElement).setSelectionRange(text.value.length, text.value.length),
    track.value(field.value as HTMLTextAreaElement, text.value))
}
onMounted(effect2)
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = open.value && field.value ? holdFieldEscape(field.value) : () => {}
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
watch(() => open.value, effect3, { flush: 'post' })
onBeforeUnmount(() => release3?.())
const effect4 = () => {
  pressed.value = focusAfterRemoval(
    pressed.value,
    props.attachments.map((attachment) => attachment.id),
    (at) => chips.value?.children[at]?.querySelector<HTMLElement>('button'),
    field.value,
  )
}
watch(() => props.attachments, effect4, { flush: 'post' })
const effect5 = () => {
  sideKey.value !== null &&
    root.value &&
    ((box: DOMRect) =>
      (side.value = box.top >= window.innerHeight - box.bottom ? 'top' : 'bottom'))(
      (root.value as HTMLElement).getBoundingClientRect(),
    )
}
onMounted(effect5)
watch(() => sideKey.value, effect5, { flush: 'post' })
let release6: (() => void) | undefined
const effect6 = () => {
  release6?.()
  const ran = agentMember({
    member: 'PromptInput',
    element: () => field.value,
    state: () => ({
      value: text.value,
      attachments: props.attachments.map((attachment) => ({
        id: attachment.id,
        label: attachment.name,
        ...(listening.removeAttachment && !props.disabled ? {} : { disabled: true }),
      })),
      streaming: props.streaming,
      disabled: props.disabled,
    }),
    actions: {
      fill: { argument: 'text', run: (value) => agentFill(field.value, value) },
      clear: () => agentFill(field.value, ''),
      submit: () =>
        (() => {
          if (props.streaming)
            throw new Error('A reply is arriving; stop it before sending a prompt.')
          if (empty.value) throw new Error('The prompt is empty, and an empty prompt is not sent.')
          submit.value()
        })(),
      stop: () =>
        (() => {
          if (!props.streaming)
            throw new Error('No reply is arriving, so there is nothing to stop.')
          emit('stop')
        })(),
      remove: { argument: 'id', run: (value) => emit('removeAttachment', value) },
    },
    withholds: () => [
      chips.value,
      listening.attach ? toolbar.value?.firstElementChild : null,
      end.value?.lastElementChild,
    ],
  })
  release6 = () => {
    ran()
  }
}
onMounted(effect6)
onBeforeUnmount(() => release6?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.root"
    :data-state="streaming ? 'streaming' : dragover ? 'dragover' : undefined"
    :data-disabled="disabled ? '' : undefined"
    :data-empty="empty ? '' : undefined"
    :data-max-rows="String(maxRows)"
    data-member="prompt-input"
  >
    <!-- frame -->
    <div
      :class="styles.frame"
      @dragover="attachable && ($event.preventDefault(), (dragover = true))"
      @dragleave="
        !($event.currentTarget as HTMLElement).contains($event.relatedTarget as Node | null) &&
        (dragover = false)
      "
      @drop="
        attachable && ($event.preventDefault(), (dragover = false), add($event.dataTransfer?.files))
      "
    >
      <!-- attachments -->
      <div v-if="attachments.length > 0" ref="chips" :class="styles.attachments">
        <template v-for="attachment in attachments" :key="attachment.id">
          <AttachmentChip
            v-if="listening.removeAttachment && !disabled"
            :name="attachment.name"
            :size="attachment.size"
            :status="attachment.status"
            :message="attachment.message"
            :removeLabel="messages.remove(attachment.name)"
            :uploadingLabel="messages.uploading(attachment.name)"
            @remove="
              ((pressed = { id: attachment.id, at: attachments.indexOf(attachment) }),
              emit('removeAttachment', attachment.id))
            "
          />
          <AttachmentChip
            v-else
            :name="attachment.name"
            :size="attachment.size"
            :status="attachment.status"
            :message="attachment.message"
            :removeLabel="messages.remove(attachment.name)"
            :uploadingLabel="messages.uploading(attachment.name)"
          />
        </template>
      </div>
      <!-- field -->
      <textarea
        ref="field"
        :class="styles.field"
        :id="id"
        :name="name"
        :rows="1"
        :value="text"
        :placeholder="placeholder"
        :disabled="disabled"
        :aria-label="label"
        :aria-autocomplete="suggesting ? 'list' : undefined"
        :aria-haspopup="suggesting ? 'listbox' : undefined"
        :aria-controls="open ? listId : undefined"
        :aria-activedescendant="open && active !== -1 ? `${uid}-suggestion-${active}` : undefined"
        @input="
          (setText(($event.target as HTMLTextAreaElement).value),
          track($event.target as HTMLTextAreaElement, ($event.target as HTMLTextAreaElement).value))
        "
        @keydown="
          !composingKey($event) &&
          !listKeys($event) &&
          $event.key === 'Enter' &&
          !$event.shiftKey &&
          ($event.preventDefault(), submit())
        "
        @keyup="track($event.currentTarget as HTMLTextAreaElement, text)"
        @pointerup="track($event.currentTarget as HTMLTextAreaElement, text)"
        @focus="track($event.currentTarget as HTMLTextAreaElement, text)"
        @blur="((caret = null), (reported = null))"
        @compositionstart="composing = true"
        @compositionend="
          ((composing = false), track($event.currentTarget as HTMLTextAreaElement, text))
        "
        @paste="
          attachable &&
          ($event.clipboardData?.files.length ?? 0) > 0 &&
          ($event.preventDefault(), add($event.clipboardData?.files))
        "
      />
      <!-- toolbar -->
      <div ref="toolbar" :class="styles.toolbar">
        <Button
          v-if="listening.attach"
          variant="ghost"
          tone="neutral"
          size="sm"
          :iconOnly="true"
          icon="attach"
          :label="messages.attach"
          :disabled="disabled"
          @click="picker?.click()"
        />
        <slot name="leading" />
        <!-- end -->
        <div ref="end" :class="styles.end">
          <slot name="trailing" />
          <Button
            v-if="streaming"
            variant="outline"
            tone="neutral"
            size="sm"
            :iconOnly="true"
            icon="stop"
            :label="messages.stop"
            @click="emit('stop')"
          />
          <Button
            v-else
            variant="solid"
            tone="accent"
            size="sm"
            :iconOnly="true"
            icon="send"
            :label="messages.send"
            :disabled="disabled || empty"
            @click="submit()"
          />
        </div>
      </div>
      <!-- picker -->
      <input
        v-if="listening.attach"
        ref="picker"
        :class="styles.picker"
        type="file"
        :accept="accept"
        :multiple="multiple"
        :disabled="disabled"
        tabindex="-1"
        @change="
          (add(($event.target as HTMLInputElement).files),
          (($event.target as HTMLInputElement).value = ''))
        "
      />
    </div>
    <!-- hint -->
    <p v-if="hint !== undefined" :class="styles.hint">
      {{ hint }}
    </p>
    <!-- suggestions -->
    <div
      v-if="open && trigger !== undefined"
      :class="styles.suggestions"
      :data-side="side"
      data-prompt-part="suggestions"
      @mousedown="$event.preventDefault()"
    >
      <!-- list -->
      <ul :class="styles.listbox" :id="listId" role="listbox" :aria-label="trigger?.label">
        <template v-for="(option, index) in shown" :key="option.id">
          <!-- option -->
          <li
            :class="styles.option"
            :id="`${uid}-suggestion-${index}`"
            role="option"
            :aria-selected="index === active ? 'true' : 'false'"
            :data-highlighted="index === active ? '' : undefined"
            @pointermove="index !== active && (highlight = { key: listKey, index })"
            @click="pick(index)"
          >
            <span v-if="option.icon !== undefined" :class="styles.glyph">
              <Icon :name="option.icon" size="sm" />
            </span>
            <span :class="styles.text">
              <span :class="styles.label">
                {{ option.label }}
              </span>
              <span v-if="option.description !== undefined" :class="styles.description">
                {{ option.description }}
              </span>
            </span>
          </li>
        </template>
      </ul>
      <div v-if="loading" :class="styles.rows" aria-hidden="true">
        <template v-for="row in [0, 1, 2]" :key="row">
          <div :class="styles.row">
            <Skeleton textStep="sm" />
          </div>
        </template>
      </div>
      <div v-if="!loading && shown.length === 0" :class="styles.empty" aria-hidden="true">
        {{ say.noSuggestions }}
      </div>
    </div>
    <div v-if="suggesting" :class="styles.status" role="status" aria-live="polite">
      {{ announcement }}
    </div>
  </div>
</template>
